    if (!this.alive) { this.tickDeath(dt); return; }
    const k = 1 - Math.exp(-12 * dt);
    this.group.position.x += (this.tx - this.group.position.x) * k;
    this.group.position.z += (this.tz - this.group.position.z) * k;
    let dy = this.tyaw - this.group.rotation.y;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.group.rotation.y += dy * k;
    if (this.moving) this.animateLegs(now / 1000, 6);
  }
